// 1. Delegate
protocol EditorDelegate: AnyObject { func editor(_ e: Editor, didSave item: Item) }
final class Editor { weak var delegate: EditorDelegate? }

// 2. Closure
final class Editor2 { var onSave: ((Item) -> Void)? }
editor2.onSave = { [weak self] item in self?.refresh(item) }

// 3. NotificationCenter
extension Notification.Name { static let itemSaved = Notification.Name("itemSaved") }
NotificationCenter.default.post(name: .itemSaved, object: item)
let token = NotificationCenter.default.addObserver(forName: .itemSaved, object: nil, queue: .main) { note in
    print(note.object as? Item as Any)
}
